function sols = solver_tdoa_rank1_53(data)
[C0,C1] = setup_elimination_template(data);
C1 = C0 \ C1;
RR = [-C1(end-0:end,:);eye(1)];
AM_ind = [1];
AM = RR(AM_ind,:);
[V,D] = eig(AM);
V = V ./ (ones(size(V,1),1)*V(1,:));
sols(1,:) = diag(D).';
warning('TODO: Extract remaining variables.');

